thread_local bool watchAllocations=false;
thread_local size_t allocationCount=0;
void* operator new(std::size_t size){if(watchAllocations)++allocationCount;if(auto* p=std::malloc(size?size:1))return p;throw std::bad_alloc();}
void* operator new[](std::size_t size){return ::operator new(size);}
void operator delete(void* p)noexcept{std::free(p);}
void operator delete[](void* p)noexcept{std::free(p);}
void require(bool ok,const char* msg){if(!ok)throw std::runtime_error(msg);}
void set(CortexProcessor& p,const char* id,float value){auto* parameter=p.state.getParameter(id);parameter->setValueNotifyingHost(parameter->convertTo0to1(value));}
double render(CortexProcessor& p,int blocks,juce::MidiBuffer& midi,bool realtime=false){juce::AudioBuffer<float> buffer(2,256);double energy=0;for(int b=0;b<blocks;++b){if(realtime)juce::Thread::sleep(5);watchAllocations=true;p.processBlock(buffer,midi);watchAllocations=false;require(allocationCount==0,"no C++ heap allocations in audio callback");for(int c=0;c<2;++c)for(int s=0;s<256;++s){auto v=buffer.getSample(c,s);require(std::isfinite(v)&&std::abs(v)<=1,"finite bounded output");energy+=v*v;}}return energy;}
int benchmark(){CortexProcessor p;p.prepareToPlay(48000,256);juce::MidiBuffer midi;juce::AudioBuffer<float> buffer(2,256);constexpr int blocks=3000;std::vector<double> times(blocks);auto measure=[&](const char* name){for(int i=0;i<400;++i)p.processBlock(buffer,midi);double sum=0;for(int i=0;i<blocks;++i){double start=juce::Time::getMillisecondCounterHiRes();watchAllocations=true;p.processBlock(buffer,midi);watchAllocations=false;times[i]=juce::Time::getMillisecondCounterHiRes()-start;sum+=times[i];}require(allocationCount==0,"benchmark callback allocations");std::sort(times.begin(),times.end());std::cout<<name<<" mean_block_ms="<<sum/blocks<<" p95_ms="<<times[blocks*95/100]<<" max_ms="<<times.back()<<" render_ms_per_audio_second="<<sum/(blocks*256./48000)<<"\n";};measure("idle");set(p,"play",1);if(p.state.getParameter("voices")){for(int i=0;i<3;++i){set(p,"voices",float(i));measure(i==0?"bed_4":i==1?"bed_8":"bed_16");}}else measure("bed_16_baseline");return 0;}
int orbitBenchmark(){CortexProcessor p;set(p,"reverb",0);set(p,"play",1);set(p,"voices",1);juce::MidiBuffer midi;juce::AudioBuffer<float> block(2,256);for(int orbit:{0,1}){set(p,"orbitEnabled",float(orbit));p.prepareToPlay(48000,256);for(int i=0;i<400;++i)p.processBlock(block,midi);double start=juce::Time::getMillisecondCounterHiRes();for(int i=0;i<3000;++i){watchAllocations=true;p.processBlock(block,midi);watchAllocations=false;}double elapsed=juce::Time::getMillisecondCounterHiRes()-start;require(allocationCount==0,"orbit benchmark noalloc");std::cout<<"HEAD_ORBIT="<<orbit<<" cap=8 render_ms_per_audio_second="<<elapsed/16<<"\n";}return 0;}
int orbitEditorSnapshot(const char* path){CortexProcessor p;set(p,"orbitEnabled",1);p.seedNode(p.centroidNode[2]);juce::Thread::sleep(80);std::unique_ptr<juce::AudioProcessorEditor> editor(p.createEditor());editor->setBounds(0,0,1440,900);for(auto* child:editor->getChildren())if(auto* viewport=dynamic_cast<juce::Viewport*>(child))viewport->setViewPosition(0,870);juce::Image image(juce::Image::ARGB,1440,900,true);juce::Graphics graphics(image);editor->paintEntireComponent(graphics,true);juce::File file(path);file.getParentDirectory().createDirectory();file.deleteFile();auto stream=file.createOutputStream();juce::PNGImageFormat png;require(stream&&png.writeImageToStream(image,*stream),"Head Orbit editor screenshot");std::cout<<"PASS actual Head Orbit editor snapshot\n";return 0;}
double tonePower(const std::vector<float>& samples,double hz){double coefficient=2*std::cos(2*3.141592653589793*hz/48000),q1=0,q2=0;for(float sample:samples){double q0=sample+coefficient*q1-q2;q2=q1;q1=q0;}return (q1*q1+q2*q2-coefficient*q1*q2)/(samples.size()*double(samples.size()));}
double peakFrequency(const std::vector<float>& samples,double center){double best=0,result=center;for(int step=-10;step<=10;++step){double hz=center+step*.02,power=tonePower(samples,hz);if(power>best){best=power;result=hz;}}return result;}
int binauralRenderChecks(){for(float x:{-.85f,-.4f,0.f,.4f,.85f})require(cortex::outputCeiling(x)==x,"ceiling exact linear below knee");for(float x:{-10.f,-2.f,-1.f,1.f,2.f,10.f})require(std::abs(cortex::outputCeiling(x))<=1&&std::abs(cortex::outputCeiling(x))>.85f,"soft ceiling bounds above knee");CortexProcessor p;set(p,"reverb",0);juce::MidiBuffer midi;juce::AudioBuffer<float> block(2,256);set(p,"binaural",1);set(p,"variation",0);set(p,"octaves",0);set(p,"root",45);set(p,"sustain",1);set(p,"decay",4);set(p,"release",5);set(p,"coupling",0);set(p,"voices",0);set(p,"output",.8f);set(p,"play",0);set(p,"pulses",0);std::vector<float> left(96000),right(96000);
 for(float delta:{2.f,8.f,50.f})for(float spread:{0.f,.5f,1.f}){set(p,"difference",delta);set(p,"spread",spread);p.prepareToPlay(48000,256);juce::Thread::sleep(35);p.eventStrength[0].store(1);p.eventNote[0].store(-1);p.pulseEpoch[0].store(p.activityEpoch.load());p.pulseCounters[0].fetch_add(1);for(int i=0;i<160;++i){p.amplitudes[0].store(1);p.processBlock(block,midi);}for(int offset=0;offset<96000;offset+=256){p.amplitudes[0].store(1);watchAllocations=true;p.processBlock(block,midi);watchAllocations=false;for(int i=0;i<256&&offset+i<96000;++i){left[offset+i]=block.getSample(0,i);right[offset+i]=block.getSample(1,i);require(std::isfinite(left[offset+i])&&std::abs(left[offset+i])<=1&&std::isfinite(right[offset+i])&&std::abs(right[offset+i])<=1,"finite pair audio");}}double square=0;for(float value:left)square+=value*value;double rms=std::sqrt(square/left.size()),oldReference=.8/16/std::sqrt(2.);require(std::abs(rms/oldReference-2)<.01,"binaural gain is twice previous single-pair RMS");double l=peakFrequency(left,110),r=peakFrequency(right,110+delta);require(std::abs(l-110)<.03&&std::abs(r-l-delta)<.03,"actual2/8/50Hz fundamental difference");require(tonePower(left,110+delta)<tonePower(left,110)*.0001&&tonePower(right,110)<tonePower(right,110+delta)*.0001,"strict independent ears at all spread");require(tonePower(left,330)<tonePower(left,110)*.000001,"binaural has no softclip third harmonic");require(p.activeVoices.load()==1,"one stereo pair counts one slot");std::cout<<"PAIR delta="<<delta<<" spread="<<spread<<" left="<<l<<" right="<<r<<"\n";}
 for(float wet:{0.f,1.f}){set(p,"reverb",wet);set(p,"voices",2);set(p,"output",1);p.prepareToPlay(48000,256);juce::Thread::sleep(35);for(int g=0;g<16;++g){p.eventStrength[g].store(1);p.eventNote[g].store(-1);p.pulseEpoch[g].store(p.activityEpoch.load());p.pulseCounters[g].fetch_add(1);}double energy=0;float maximum=0;for(int b=0;b<512;++b){for(auto& amplitude:p.amplitudes)amplitude.store(1);watchAllocations=true;p.processBlock(block,midi);watchAllocations=false;for(int ch=0;ch<2;++ch)for(int i=0;i<256;++i){float value=block.getSample(ch,i);require(std::isfinite(value)&&std::abs(value)<=1,"sixteen full-strength pairs bounded dry and wet");maximum=std::max(maximum,std::abs(value));energy+=value*value;}}require(p.activeVoices.load()==16&&energy>1,"all sixteen pairs exercised");std::cout<<"FULL16 wet="<<wet<<" peak="<<maximum<<"\n";}
 require(allocationCount==0,"binaural callback is allocation free");set(p,"binaural",0);p.stopEverything();render(p,300,midi);require(render(p,20,midi)==0,"pair shutdown reaches silence");std::cout<<"PASS gain2x, actual carrier frequencies, strictchannelisolation, purefundamentals, boundedpairs andnoallocations\n";return 0;}
