 require(CortexAnatomy::brain_positions_binSize==65536*3*4&&CortexAnatomy::brain_normals_binSize==65536*3*4,"embedded exact 65536 anatomy points and normals");for(int i=0;i<65536;++i){float normal[3],position[3];std::memcpy(normal,CortexAnatomy::brain_normals_bin+i*12,12);std::memcpy(position,CortexAnatomy::brain_positions_bin+i*12,12);require(std::isfinite(position[0])&&std::isfinite(position[1])&&std::isfinite(position[2]),"finite source geometry");require(std::abs(normal[0]*normal[0]+normal[1]*normal[1]+normal[2]*normal[2]-1)<.001,"unit surface normals");}
