 if(argc>1){set(p,"pulses",1);set(p,"rate",2);std::unique_ptr<juce::AudioProcessorEditor> editor(p.createEditor());editor->setBounds(0,0,1440,900);p.seedNode(p.centroidNode[2]);juce::Thread::sleep(80);juce::Image image(juce::Image::ARGB,1440,900,true);juce::Graphics graphics(image);double totalPaint=0,maxPaint=0;for(int frame=0;frame<12;++frame){double start=juce::Time::getMillisecondCounterHiRes();editor->paintEntireComponent(graphics,true);double elapsed=juce::Time::getMillisecondCounterHiRes()-start;totalPaint+=elapsed;maxPaint=std::max(maxPaint,elapsed);}std::cout<<"EDITOR 65536 points 1440x900: average paint "<<totalPaint/12<<" ms, maximum "<<maxPaint<<" ms\n";juce::File snapshotFile(argv[1]);snapshotFile.deleteFile();juce::FileOutputStream output{snapshotFile};juce::PNGImageFormat png;require(png.writeImageToStream(image,output),"snapshot saved");}
